struct Window {                          // RAII staging: map, then unmap
    Window(int fd, off_t off, size_t len)
        : p(mmap(nullptr, len, PROT_READ, MAP_PRIVATE, fd, off)), n(len) {}
    ~Window() { if (p != MAP_FAILED) munmap(p, n); }
    const std::byte* p; size_t n;
};
Window w(fd, ix.off + want.offset, want.len);   // only this range is mapped
consume(w.p, w.n);                              // pages fault in as touched

generator<Part> parts(const Index& ix) {          // stage 1 handed in as data
    for (const auto& range : ix.wanted) {
        auto data = fetch(range);                  // stage 2, one part at a time
        co_yield Part{range.id, std::move(data)};
    }
}
for (const Part& p : parts(ix)) consume(p);        // pull; early break destroys state
